#!/usr/bin/env node
/**
 * Class names defined in CSS that nothing in the app appears to use.
 *
 * Reports rather than deletes, and that is deliberate: the first pass of this
 * found 98 names, and several were live —
 *
 *   - `.ui-panel--surface`, `.ui-btn--ghost` and friends are assembled at
 *     runtime (`ui-panel--${tone}`), so no literal exists to grep for;
 *   - `.markedContent` is generated by pdf.js inside the text layer, so it
 *     appears in node_modules and nowhere in src.
 *
 * Both would have been deleted by a bulk sweep, and the second one silently:
 * nothing renders `.markedContent` in this repo's own source at all. So the
 * output below is a list to check by hand, one at a time, not a list to pipe
 * into a delete. The runtime-composed prefixes are filtered out; anything from
 * an external library still has to be recognised by a person.
 *
 * Usage: node scripts/find-dead-css.mjs
 */
import { readFileSync, readdirSync, statSync } from "node:fs";
import { join, extname } from "node:path";

const SRC = new URL("../src", import.meta.url).pathname;

function walk(dir, out = []) {
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) walk(full, out);
    else out.push(full);
  }
  return out;
}

const files = walk(SRC);
const code = files
  .filter((f) => [".ts", ".tsx"].includes(extname(f)))
  .map((f) => readFileSync(f, "utf8"))
  .join("\n");

// `foo--${variant}` / `foo-${id}`: the literal never appears, the rule is live.
const composed = new Set(
  [...code.matchAll(/([a-z][\w-]*?)-{1,2}\$\{/g)].map((m) => m[1]),
);

const defined = new Set();
for (const f of files.filter((f) => extname(f) === ".css")) {
  // Comments first: this file's own prose names the rules it explains, and a
  // scanner that reads them reports them as defined and then as dead.
  const css = readFileSync(f, "utf8").replace(/\/\*[\s\S]*?\*\//g, "");
  for (const m of css.matchAll(/(^|[\s,>+~])\.([A-Za-z][\w-]*)/gm)) {
    defined.add(m[2]);
  }
}

const suspect = [...defined]
  .filter((c) => !code.includes(c))
  .filter((c) => ![...composed].some((p) => c.startsWith(`${p}-`)))
  .sort();

console.log(`${defined.size} class names defined, ${suspect.length} with no literal use in src/:\n`);
for (const c of suspect) console.log(`  .${c}`);
console.log(
  "\nCheck each by hand before removing — a name may be composed at runtime or " +
    "come from a library's own DOM (pdf.js writes .markedContent).",
);
